import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem94 corrige tipo de codigo sem autenticar calcados ou alterar operacao',()=>{for(const [id,titulo] of [['mlMLB3966936389','Tênis Mormaii Urban Free Masculino Casual Original Skate Nfe'],['mlMLB3973124591','Sapatênis Masculino Casual Com Cadarço Dia A Dia Versátil'],['mlMLB4028845341','Tênis Kappa Run 200 Original Caminhada Academia']]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.equal(x.titulo,titulo);assert.deepEqual(correctProductData(x),x);assert.match(x.comentario,/anúncio do vendedor, não um código de catálogo confirmado/);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/autenticidade comprovada|amortecimento comprovado|couro legítimo/i);}});
